                                                                                                                                                                                                    def 기본서식진하게괄호(self):
                                                                                                                                                                                                        블록스캔 = self.블록스캔()
                                                                                                                                                                                                        텍스트 = 블록스캔[1]
                                                                                                                                                                                                        if '\r' not in 텍스트:
                                                                                                                                                                                                            self.대상.HAction.Run('DeleteBack')
                                                                                                                                                                                                            시작지점 = self.현재위치()
                                                                                                                                                                                                            텍스트 = 텍스트.replace('(', '')
                                                                                                                                                                                                            텍스트 = 텍스트.replace(')', '')
                                                                                                                                                                                                            self.문장('(' + 텍스트 + ')')
                                                                                                                                                                                                            종료지점 = self.현재위치()
                                                                                                                                                                                                            self.대상.SetPosBySet(시작지점)
                                                                                                                                                                                                            self.대상.HAction.Run('Select')
                                                                                                                                                                                                            self.대상.SetPosBySet(종료지점)
                                                                                                                                                                                                            self.기본글자()
                                                                                                                                                                                                            self.진하게()
                                                                                                                                                                                                        return None

                                                                                                                                                                                                    
